mapper.select:
SELECT id FROM schedule_items
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND slot_id = #{slotId}
AND id <> #{itemId}
LIMIT 1

SELECT coalesce(max(sort_order) + 1, 0) FROM schedule_items
WHERE space_id = #{spaceId} AND event_id = #{eventId}
  AND day = #{day} AND start_time = CAST(#{startTime} AS time)
